using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.TKT.EstadosTickets;using GraphApi.Services.TKT.EstadosTickets;namespace GraphApi.Controllers.TKT.EstadosTickets{    /// <summary>    /// Gestión de EstadosTickets: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("TKT/Legacy/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre EstadosTickets")]    public class EstadosTicketsController : Controller    {        private readonly IEstadosTicketsService _objService;        public EstadosTicketsController(IEstadosTicketsService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los EstadosTickets, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="estadoTicketID">EstadoTicketID</param>        /// <param name="estadoTicket">EstadoTicket</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de EstadosTickets</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar EstadosTickets",            Description = "Devuelve EstadosTickets aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadEstadosTickets>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadEstadosTickets>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? estadoTicketID,            [FromQuery] string? estadoTicket,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetEstadosTicketsDynamic(                estadoTicketID,                 estadoTicket,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo EstadosTicket.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del EstadosTicket a crear.</param>        /// <returns>El EstadosTicket recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear EstadosTickets",            Description = "Inserta un nuevo EstadosTicket en la base de datos."        )]        [ProducesResponseType(typeof(clReadEstadosTickets), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadEstadosTickets>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateEstadosTickets objInput)        {            var vCreated = await _objService.CreateEstadosTickets(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de EstadosTicket.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del EstadosTicket.</param>        /// <returns>El EstadosTicket actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar EstadosTickets",            Description = "Actualiza uno o varios campos de EstadosTicket existente."        )]        [ProducesResponseType(typeof(clReadEstadosTickets), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadEstadosTickets>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateEstadosTickets objInput)        {            var vUpdated = await _objService.UpdateEstadosTickets(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un EstadosTicket por su ID.        /// </summary>        [HttpDelete("{nEstadosTicketsID:int}")]        [SwaggerOperation(            Summary = "Eliminar EstadosTicket",            Description = "Borra un EstadosTicket si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nEstadosTicketsID)        {            var success = await _objService.DeleteEstadosTickets(nEstadosTicketsID);            return success ? NoContent() : NotFound();        }    }}